pub fn append_one_with_empty_roots(
        &self,
        leaf: Digest,
        empty: &[Digest; POOL_V1_TREE_DEPTH + 1],
    ) -> Result<(Self, AppendOneV1), PoolV1TreeError> {
        let validated = ValidatedIncrementalMerkleTreeV1::from_parts(
            self.next_leaf_index,
            self.root,
            self.frontier,
            empty,
        )?;
        validated
            .append_one(leaf)
            .map(|(next, receipt)| (next.into_inner(), receipt))
    }

pub fn decode_pool_v1_pair_forest_lane_state_v1(
    bytes: &[u8],
    pair_empty_roots: &[Digest; POOL_V1_TREE_DEPTH + 1],
) -> Result<PoolV1PairForestLaneStateV1, PoolV1PairForestAccountErrorV1> {
    if bytes.len() != POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES {
        return Err(PoolV1PairForestAccountErrorV1::WrongLength);
    }
    if bytes[..4] != POOL_V1_PAIR_FOREST_LANE_MAGIC {
        return Err(PoolV1PairForestAccountErrorV1::WrongMagic);
    }
    if bytes[4] != POOL_V1_PAIR_FOREST_LANE_VERSION {
        return Err(PoolV1PairForestAccountErrorV1::WrongVersion);
    }
    if usize::from(bytes[5]) >= POOL_V1_PAIR_FOREST_LANE_COUNT {
        return Err(PoolV1PairForestAccountErrorV1::InvalidLane);
    }
    if bytes[6] != POOL_V1_PAIR_FOREST_LANE_COUNT as u8 {
        return Err(PoolV1PairForestAccountErrorV1::WrongLaneCount);
    }
    if bytes[7] != POOL_V1_TREE_DEPTH as u8 {
        return Err(PoolV1PairForestAccountErrorV1::WrongDepth);
    }
    if bytes[8..40] != POOL_V1_PAIR_FOREST_ACCOUNT_FORMAT_BINDING {
        return Err(PoolV1PairForestAccountErrorV1::WrongFormatBinding);
    }
    let master: [u8; 32] = bytes[LANE_MASTER_OFFSET..72].try_into().unwrap();
    if master == [0u8; 32] {
        return Err(PoolV1PairForestAccountErrorV1::ZeroRequiredBinding);
    }
    if bytes[73..LANE_TREE_OFFSET].iter().any(|byte| *byte != 0) {
        return Err(PoolV1PairForestAccountErrorV1::NonZeroReserved);
    }
    let tree = IncrementalMerkleTreeV1::decode_with_empty_roots(
        &bytes[LANE_TREE_OFFSET..],
        pair_empty_roots,
    )?;
    if tree.next_leaf_index > POOL_V1_PAIR_CAPACITY {
        return Err(PoolV1PairForestAccountErrorV1::InvalidMasterState);
    }
    Ok(PoolV1PairForestLaneStateV1 {
        bump: bytes[72],
        master,
        lane_id: bytes[5],
        tree,
    })
}

pub fn encode_pool_v1_pair_forest_lane_state_v1(
    lane: &PoolV1PairForestLaneStateV1,
    pair_empty_roots: &[Digest; POOL_V1_TREE_DEPTH + 1],
) -> Result<[u8; POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES], PoolV1PairForestAccountErrorV1> {
    if usize::from(lane.lane_id) >= POOL_V1_PAIR_FOREST_LANE_COUNT {
        return Err(PoolV1PairForestAccountErrorV1::InvalidLane);
    }
    if lane.master == [0u8; 32] {
        return Err(PoolV1PairForestAccountErrorV1::ZeroRequiredBinding);
    }
    if lane.tree.next_leaf_index > POOL_V1_PAIR_CAPACITY {
        return Err(PoolV1PairForestAccountErrorV1::InvalidMasterState);
    }
    let tree = lane.tree.encode_with_empty_roots(pair_empty_roots)?;
    let mut output = [0u8; POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES];
    output[..4].copy_from_slice(&POOL_V1_PAIR_FOREST_LANE_MAGIC);
    output[4] = POOL_V1_PAIR_FOREST_LANE_VERSION;
    output[5] = lane.lane_id;
    output[6] = POOL_V1_PAIR_FOREST_LANE_COUNT as u8;
    output[7] = POOL_V1_TREE_DEPTH as u8;
    output[8..40].copy_from_slice(&POOL_V1_PAIR_FOREST_ACCOUNT_FORMAT_BINDING);
    output[LANE_MASTER_OFFSET..72].copy_from_slice(&lane.master);
    output[72] = lane.bump;
    output[LANE_TREE_OFFSET..].copy_from_slice(&tree);
    Ok(output)
}

pub fn leaf_digest(&self) -> Result<Digest, PoolV1PairLeafErrorV1> {
        self.validate()?;
        Ok(pool_v1_tree_parent(
            &self.first_commitment,
            &self.second_commitment,
        ))
    }

pub fn single_output(first_commitment: Digest) -> Result<Self, PoolV1PairLeafErrorV1> {
        let result = Self {
            first_commitment,
            second_occupied: M31::ZERO,
            second_commitment: [M31::ZERO; 8],
            second_occupancy_inverse: M31::ZERO,
        };
        result.validate()?;
        Ok(result)
    }

pub fn validate(&self) -> Result<(), PoolV1PairLeafErrorV1> {
        if !digest_is_canonical(&self.first_commitment)
            || !digest_is_canonical(&self.second_commitment)
        {
            return Err(PoolV1PairLeafErrorV1::NonCanonicalCommitment);
        }
        if self.second_occupied.0 >= P {
            return Err(PoolV1PairLeafErrorV1::NonCanonicalOccupancy);
        }
        if self.second_occupancy_inverse.0 >= P {
            return Err(PoolV1PairLeafErrorV1::NonCanonicalInverse);
        }

        let one_minus_occupied = M31::ONE.sub(self.second_occupied);
        if self.second_occupied.mul(self.second_occupied.sub(M31::ONE)) != M31::ZERO {
            return Err(PoolV1PairLeafErrorV1::OccupancyNotBoolean);
        }
        if self.second_sentinel().mul(self.second_occupancy_inverse) != self.second_occupied {
            return Err(PoolV1PairLeafErrorV1::SentinelInverseMismatch);
        }
        if one_minus_occupied.mul(self.second_occupancy_inverse) != M31::ZERO {
            return Err(PoolV1PairLeafErrorV1::EmptyInverseNonZero);
        }
        if self
            .second_commitment
            .iter()
            .any(|limb| one_minus_occupied.mul(*limb) != M31::ZERO)
        {
            return Err(PoolV1PairLeafErrorV1::EmptyCommitmentNonZero);
        }
        if self.second_occupied == M31::ONE && self.second_sentinel() == M31::ZERO {
            return Err(PoolV1PairLeafErrorV1::OccupiedSentinelZero);
        }
        Ok(())
    }

pub fn note_commitment(owner_key: &Digest, value: u32, asset_id: M31, salt: &Digest) -> Digest {
    note_commitment_with(owner_key, value, asset_id, salt, &mut hash_fields)
}

fn note_commitment_with<H>(
    owner_key: &Digest,
    value: u32,
    asset_id: M31,
    salt: &Digest,
    hash: &mut H,
) -> Digest
where
    H: FnMut(M31, &[M31]) -> Digest,
{
    debug_assert!(value < P);
    let mut input = Vec::with_capacity(18);
    append_digest(&mut input, owner_key);
    input.push(M31(value));
    input.push(asset_id);
    append_digest(&mut input, salt);
    hash(DOMAIN_NOTE, &input)
}

pub(crate) fn decode_deposit_instruction_with_magic_v1(
    bytes: &[u8],
    expected_magic: [u8; 4],
) -> Result<DepositRequestV1<'_>, DepositInstructionFormatErrorV1> {
    if bytes.len() < POOL_V1_DEPOSIT_INSTRUCTION_HEADER_BYTES
        || bytes.len() > POOL_V1_DEPOSIT_INSTRUCTION_MAX_BYTES
    {
        return Err(DepositInstructionFormatErrorV1::WrongLength);
    }
    if bytes[..4] != expected_magic {
        return Err(DepositInstructionFormatErrorV1::WrongMagic);
    }
    if bytes[4] != POOL_V1_DEPOSIT_INSTRUCTION_VERSION {
        return Err(DepositInstructionFormatErrorV1::WrongVersion);
    }
    if bytes[5] != 0 || bytes[44..48] != [0u8; 4] {
        return Err(DepositInstructionFormatErrorV1::NonZeroReserved);
    }

    let declared_payload_length = usize::from(u16::from_le_bytes(
        bytes[6..8]
            .try_into()
            .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?,
    ));
    if declared_payload_length > POOL_V1_ENCRYPTED_NOTE_PAYLOAD_MAX_BYTES {
        return Err(DepositInstructionFormatErrorV1::InvalidPayloadLength);
    }
    let expected_length = INSTRUCTION_PAYLOAD_OFFSET
        .checked_add(declared_payload_length)
        .ok_or(DepositInstructionFormatErrorV1::WrongLength)?;
    if bytes.len() != expected_length {
        return Err(DepositInstructionFormatErrorV1::WrongLength);
    }

    let owner_key_bytes: &[u8; 32] = bytes[INSTRUCTION_OWNER_KEY_OFFSET..INSTRUCTION_AMOUNT_OFFSET]
        .try_into()
        .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?;
    let salt_bytes: &[u8; 32] = bytes[INSTRUCTION_SALT_OFFSET..INSTRUCTION_PAYLOAD_OFFSET]
        .try_into()
        .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?;
    let owner_key = decode_digest_canonical(owner_key_bytes)
        .map_err(|_| DepositInstructionFormatErrorV1::NonCanonicalDigest)?;
    let salt = decode_digest_canonical(salt_bytes)
        .map_err(|_| DepositInstructionFormatErrorV1::NonCanonicalDigest)?;
    let amount = u32::from_le_bytes(
        bytes[INSTRUCTION_AMOUNT_OFFSET..44]
            .try_into()
            .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?,
    );
    if amount == 0 || amount >= VALUE_LIMIT {
        return Err(DepositInstructionFormatErrorV1::InvalidAmount);
    }

    Ok(DepositRequestV1 {
        owner_key,
        amount,
        salt,
        encrypted_note_payload: &bytes[INSTRUCTION_PAYLOAD_OFFSET..],
    })
}

pub(crate) fn append_roots_unchecked(data: &mut [u8], header: RootPageHeaderV1, roots: &[Digest]) {
    debug_assert!(usize::from(header.filled) + roots.len() <= POOL_V1_ROOT_HISTORY_CAPACITY);
    for (offset, root) in roots.iter().enumerate() {
        let slot = usize::from(header.filled) + offset;
        let start = PAGE_ROOTS_OFFSET + slot * 32;
        data[start..start + 32].copy_from_slice(&encode_digest_canonical(root));
    }
    let filled = header.filled + roots.len() as u16;
    data[PAGE_FILLED_OFFSET..58].copy_from_slice(&filled.to_le_bytes());
}

pub fn pool_v1_root_page_address(
    program_id: &Pubkey,
    pool: &Pubkey,
    page_number: u64,
) -> (Pubkey, u8) {
    let page_number_bytes = page_number.to_le_bytes();
    Pubkey::find_program_address(
        &[
            POOL_V1_ROOT_HISTORY_PAGE_SEED,
            pool.as_ref(),
            &page_number_bytes,
        ],
        program_id,
    )
}

fn decode_deposit_lane_box_v1(
    program_id: &Pubkey,
    master: &Pubkey,
    lane_id: u8,
    lane_account: &AccountInfo<'_>,
) -> Result<Box<PoolV1PairForestLaneStateV1>, ProgramError> {
    #[cfg(feature = "pair-forest-deposit-invariant-audit")]
    return Ok(Box::new(decode_lane_account_from_program_invariant_v1(
        program_id,
        master,
        lane_id,
        lane_account,
        true,
    )?));

    #[cfg(not(feature = "pair-forest-deposit-invariant-audit"))]
    Ok(Box::new(decode_lane_account(
        program_id,
        master,
        lane_id,
        lane_account,
        true,
    )?))
}

fn decode_lane_account(
    program_id: &Pubkey,
    master: &Pubkey,
    expected_lane: u8,
    account: &AccountInfo<'_>,
    writable: bool,
) -> Result<PoolV1PairForestLaneStateV1, ProgramError> {
    require_program_account(account, program_id, writable)?;
    // Stored canonical bump (G_R1.8). On a mismatch the canonical search runs
    // only to reproduce the previous rejection codes: a non-canonical key is
    // an address error, a canonical key with a wrong stored bump is a state
    // error after decoding.
    let stored = stored_lane_bump(account)?;
    let fast = match stored {
        Some(bump) => lane_address_matches(program_id, master, expected_lane, bump, account.key)?,
        None => false,
    };
    let (expected, bump) = if fast {
        (*account.key, stored.unwrap_or_default())
    } else {
        pool_v1_pair_forest_lane_address(program_id, master, expected_lane)?
    };
    if account.is_signer || account.key != &expected {
        return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
    }
    let lane = decode_pool_v1_pair_forest_lane_state_v1(
        &account.try_borrow_data()?,
        &POOL_V1_PAIR_EMPTY_ROOTS,
    )
    .map_err(|_| PoolV1ProgramError::InvalidAccountType)?;
    if lane.master != master.to_bytes() || lane.lane_id != expected_lane || lane.bump != bump {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }
    Ok(lane)
}

fn prepare_deposit_append_v1(
    lane: &PoolV1PairForestLaneStateV1,
    lane_id: u8,
    pair_leaf: Digest,
) -> Result<
    (
        AppendOneV1,
        Box<[u8; POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES]>,
    ),
    ProgramError,
> {
    #[cfg(not(feature = "pair-forest-deposit-invariant-audit"))]
    let (next_tree, append) = lane
        .tree
        .append_one_with_empty_roots(pair_leaf, &POOL_V1_PAIR_EMPTY_ROOTS)
        .map_err(|_| PoolV1ProgramError::StateHistoryMismatch)?;
    #[cfg(feature = "pair-forest-deposit-invariant-audit")]
    let (next_tree, append) = append_pair_leaf_from_program_invariant_v1(&lane.tree, pair_leaf)?;
    let next_lane = Box::new(PoolV1PairForestLaneStateV1 {
        bump: lane.bump,
        master: lane.master,
        lane_id,
        tree: next_tree,
    });
    #[cfg(not(feature = "pair-forest-deposit-invariant-audit"))]
    let next_lane_image = Box::new(
        encode_pool_v1_pair_forest_lane_state_v1(&next_lane, &POOL_V1_PAIR_EMPTY_ROOTS)
            .map_err(|_| PoolV1ProgramError::StateHistoryMismatch)?,
    );
    #[cfg(feature = "pair-forest-deposit-invariant-audit")]
    let next_lane_image = Box::new(encode_lane_from_authenticated_result_v1(&next_lane)?);
    Ok((append, next_lane_image))
}

fn require_exact_account_count(accounts: &[AccountInfo<'_>], expected: usize) -> ProgramResult {
    if accounts.len() != expected {
        return Err(if accounts.len() < expected {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    Ok(())
}
